import React, { useEffect, useState } from 'react';
import { Col, Row } from 'reactstrap';
import CustomButton from 'components/CustomButton';
import { Card, CardContent, Checkbox, FormControlLabel } from '@material-ui/core';
import useAppProvider from 'providers/useAppProvider';
import { themeList } from 'config/themeList';
import ConfirmModal from '../Common/ConfirmModal';
import { getGlobalSchoolUtils, getLocalStore } from 'utils/commonFunc';
import { fetchSchoolCommonConfigServiceApi, updateSchoolConfigServiceApi } from 'actions/admin/config';
import { updateTheme } from 'providers/AppProvider';
import constants from 'config/constants';
import Paper from '@material-ui/core/Paper';
import Tab from '@material-ui/core/Tab';
import Tabs from '@material-ui/core/Tabs';
import { setCommonParam } from 'actions/admin/auth';
import { useSelector } from 'react-redux';
import AirplayIcon from '@material-ui/icons/Airplay';
import { ScrollTabPanel } from '../Reports';
import colors from 'config/colors.js';

const tabList = [{ tabIndex: 0, tabTitle: 'App Theme', query: 'app-theme', icon: <AirplayIcon /> }];

const initialConfirmState = { isConfirmModalOpen: false, message: '' };

function AppThemeSelector(props) {
  const logUser = getLocalStore('loggedUser') || {};
  const { appTheme = '', themeConfigId, setProviderState } = useAppProvider();
  const [selectedTheme, selectTheme] = useState('');
  const [confirmModal, setConfirmModal] = useState(initialConfirmState);
  const [themeSaving, setThemeSaving] = useState(false);
  const { isConfirmModalOpen, message } = confirmModal;
  const { appThemeActiveTab: activeTab = 0 } = useSelector(state => state?.auth);

  useEffect(() => {
    selectTheme(appTheme);
  }, [appTheme]);

  const toggleActivityTab = (event, tabIndex) => {
    const { activeTab } = props;
    if (tabIndex !== undefined && activeTab !== tabIndex) {
      setCommonParam('appThemeActiveTab', tabIndex);
      const cTab = tabList.find(dto => dto.tabIndex === tabIndex);
      if (cTab) {
        props.history.push(`${props.location.pathname}?${cTab.query}`);
      }
    }
  };

  useEffect(() => {
    const { search = null } = props?.location || {};
    if (search) {
      const cTab = tabList.find(dto => search.includes(dto.query));
      if (cTab) {
        toggleActivityTab(null, cTab.tabIndex);
      } else {
        toggleActivityTab(null, 0);
      }
    } else {
      toggleActivityTab(null, 0);
    }
  }, []);

  const cancelConfirm = () => {
    setConfirmModal(initialConfirmState);
  };

  const confirmUpdate = async () => {
    cancelConfirm();
    const globalSchool = getGlobalSchoolUtils();
    const loggedUser = getLocalStore('loggedUser');
    setThemeSaving(true);
    await updateSchoolConfigServiceApi({
      method: 'put',
      postData: {
        configId: themeConfigId,
        configName: 'APP_THEME',
        configValue: selectedTheme,
        schoolId: globalSchool?.schoolId,
      },
      token: loggedUser?.accessToken,
    });
    setThemeSaving(false);
    const configData = await fetchSchoolCommonConfigServiceApi({
      schoolId: loggedUser?.schoolId,
      token: loggedUser?.accessToken,
    });
    updateTheme(configData, setProviderState);
  };

  const applyTheme = () => {
    setConfirmModal(prevState => ({
      ...prevState,
      isConfirmModalOpen: true,
      message: 'Are you sure you want to update?',
    }));
  };

  const AppTheme = () => {
    return (
      <>
        <Row className="mb-3">
          <Col>
            <span style={{ color: 'green' }}>
              * Theme change is only applicable for Web portal. It will not change Mobile App theme
            </span>
            <CustomButton
              style={{ float: 'right', fontWeight: 'bold' }}
              variant="contained"
              color="secondary"
              onClick={() => applyTheme()}
              name="SELECT & APPLY"
              disabled={selectedTheme === appTheme || themeSaving || logUser?.userRole !== constants.roles.admin}
              showLoader
              loading={themeSaving}
            />
          </Col>
        </Row>
        <Row>
          {themeList.map((el, i) => {
            return (
              <Col key={i} md={6} className="mb-4">
                <Card style={{ border: el.theme === selectedTheme ? '2px solid #f50157' : 'none' }}>
                  <CardContent>
                    <FormControlLabel
                      control={
                        <Checkbox
                          checked={el.theme === selectedTheme}
                          onChange={() => selectTheme(el?.theme)}
                          name="checkedB"
                          color="secondary"
                          disabled={logUser?.userRole !== constants.roles.admin}
                        />
                      }
                      label={el.label}
                    />
                    <img src={el.logo} alt="test" />
                  </CardContent>
                </Card>
              </Col>
            );
          })}
        </Row>
      </>
    );
  };

  return (
    <div className="content">
      <Paper elevation={3} style={{ minHeight: '425px', backgroundColor: '#F4F6F8' }}>
        <Paper square elevation={3}>
          <Tabs
            value={activeTab}
            onChange={(e, tabIndex) => toggleActivityTab(e, tabIndex)}
            indicatorColor=""
            textColor={'inherit'}
            variant="fullWidth"
            scrollButtons="auto"
            aria-label="scrollable force tabs example">
            {tabList.map(item => {
              return (
                <Tab
                  key={item.tabIndex}
                  icon={item?.icon}
                  label={item.tabTitle}
                  style={{
                    fontWeight: 'bold',
                    color: activeTab === item.tabIndex ? colors.accent : '',
                    borderBottom: activeTab === item.tabIndex ? `3px solid ${colors.accent}` : '',
                  }}
                />
              );
            })}
          </Tabs>
        </Paper>
        <ScrollTabPanel value={activeTab} index={0} style={{ padding: 10 }}>
          <AppTheme />
        </ScrollTabPanel>
      </Paper>
      <ConfirmModal
        confirmModalOpen={isConfirmModalOpen}
        confirmMessage={message}
        deleteConfirm={confirmUpdate}
        deleteCancel={cancelConfirm}
      />
    </div>
  );
}

export default AppThemeSelector;
